css:
@font-face{font-family:"Archivo";font-style:normal;font-display:swap;font-weight:100 900;font-stretch:62% 125%;src:url(/assets/fonts/archivo-var-v1.woff2) format("woff2")}
@font-face{font-family:"APW Head Fallback";src:local("Arial Bold"),local("Arial-BoldMT"),local("Arial");size-adjust:74%;ascent-override:118%;descent-override:26%;line-gap-override:0%}
:root{--f-text:"Archivo",ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif;--f-head:"Archivo","APW Head Fallback","Arial Narrow",Arial,sans-serif}
body{margin:0;background:#070B1B}
*{box-sizing:border-box}
.apw{--bg:#FFFFFF;--bg2:#F6F4EF;--bg3:#E4EEF8;--card:#FFFFFF;--ink:#0E1430;--ink2:#3E4668;--mute:#4A5272;--line:#E2DDD2;--line2:#B9BED3;--field:#8A91B0;--accent:#FF4A1C;--accent-hi:#FF6B42;--accent-ink:#0E1430;--accent-text:#B02A08;--accent-soft:#FFE1D6;--ok:#1E7A52;--ok-soft:#E3F1EA;--band:#0A0F24;--band2:#111936;--shadow:0 14px 34px rgba(10,15,36,.14);font-family:var(--f-text);font-stretch:104%;-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}
.apw.dark{--bg:#0A0F24;--bg2:#0E1530;--bg3:#101A38;--card:#141D3D;--ink:#F6F4EF;--ink2:#D5DAF0;--mute:#AEB5D8;--line:rgba(255,255,255,.14);--line2:rgba(255,255,255,.3);--field:#6B7398;--accent-text:#FF8A66;--accent-soft:rgba(255,74,28,.16);--ok:#4CC38A;--ok-soft:rgba(76,195,138,.15);--band:#070B1B;--band2:#111936;--shadow:0 18px 40px rgba(0,0,0,.5)}
.apw a{color:var(--accent-text)}.mono{font-family:var(--f-text);font-stretch:104%;font-variant-numeric:tabular-nums}.wm{font-family:var(--f-head);font-weight:800;text-transform:uppercase;letter-spacing:.045em;line-height:1}.eb{margin:0;font-size:15px;font-weight:700;line-height:1.4;color:var(--mute)}.h1{margin:0;font-family:var(--f-head);font-stretch:68%;font-weight:850;letter-spacing:-.006em;line-height:.92;text-wrap:balance}.h2{margin:0;font-family:var(--f-head);font-stretch:68%;font-weight:850;font-size:clamp(40px,11vw,50px);letter-spacing:-.006em;line-height:.96;text-wrap:balance}.lead{margin:14px 0 0;font-size:18px;line-height:1.55;color:var(--ink2)}.nb{white-space:nowrap}.btn{display:flex;align-items:center;justify-content:center;gap:10px;min-height:58px;padding:0 26px;border-radius:12px;border:2px solid transparent;font-family:var(--f-head);font-stretch:88%;font-size:20px;font-weight:750;letter-spacing:.004em;line-height:1;cursor:pointer;text-decoration:none;white-space:nowrap}.btn:disabled{opacity:.45;cursor:not-allowed}.btn:not(:disabled):active{transform:translateY(1px)}.apw .btn-dot{background:var(--accent);color:var(--accent-ink)}.apw .btn-dot:not(:disabled):hover{background:var(--accent-hi);color:var(--accent-ink)}.apw .btn-ink{background:var(--ink);color:var(--bg)}.apw .btn-line{background:transparent;color:var(--ink);border-color:var(--line2)}.apw .btn-line:hover{border-color:var(--ink)}.apw .btn-line-n{background:transparent;color:#FFFFFF;border-color:rgba(255,255,255,.34)}.apw .btn-line-n:hover{border-color:#FFFFFF}.apw .btn-pay{background:#000000;color:#FFFFFF;border-color:#000000}.apw.dark .btn-pay{border-color:rgba(255,255,255,.4)}.ibtn{width:48px;height:48px;flex:0 0 48px;display:grid;place-items:center;border-radius:12px;border:2px solid var(--line2);background:transparent;color:var(--ink);cursor:pointer;padding:0;text-decoration:none}.apw .ibtn-n{border-color:rgba(255,255,255,.3);color:#F6F4EF}.ldot{display:inline-block;width:9px;height:9px;flex:0 0 9px;border-radius:50%;background:#FF4A1C}details>summary{list-style:none;cursor:pointer}details>summary::-webkit-details-marker{display:none}.chev{transition:transform .2s ease}details[open]>summary .chev{transform:rotate(45deg)}input:focus-visible,button:focus-visible,a:focus-visible,summary:focus-visible,textarea:focus-visible,ul:focus-visible{outline:3px solid #FF6B42;outline-offset:2px}.apw .btn-dot:focus-visible{outline-color:#F6F4EF}@media (prefers-reduced-motion:reduce){.chev{transition:none}}
/* Sign up. Joe, Nov 17 and 18, 2026: "We're treating 70 year olds", "so simple for the older community and for the younger
   community". Nothing here is under 15px, form words are 17 to 18px, every button is 48px tall or more, one job a screen. */
.apw .bh1{margin:0;font-family:var(--f-head);font-stretch:70%;font-weight:850;font-size:44px;letter-spacing:-.004em;line-height:.96;text-wrap:balance;outline:none}
.apw.bk{align-items:center}
.apw .bk-top,.apw .bk-prog,.apw .bk-body,.apw .bk-bar{width:100%;max-width:560px}
.apw .bk-top{display:flex;align-items:center;gap:8px;height:60px;flex:0 0 60px;padding:0 8px}
.apw .bk-tt{flex:1;margin:0;text-align:center;font-size:18px;font-weight:700}
.apw .bk-prog{flex:0 0 auto;padding:0 20px}
.apw .bk-segs{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px}
.apw .bk-segs span{display:block;height:5px;border-radius:4px}
.apw .bk-step{margin:8px 0 0;font-size:15px;color:var(--mute)}
.apw .bk-body{flex:1;min-height:0;overflow-y:auto;padding:18px 20px 28px}
.apw .bk-lead{margin:12px 0 0;font-size:17px;line-height:1.5;color:var(--ink2)}
.apw .bk-opts{display:flex;flex-direction:column;gap:10px;margin-top:18px}
.apw .bk-city{display:flex;align-items:center;gap:10px;width:100%;min-height:64px;padding:0 20px;border-radius:12px;border:2px solid var(--line);background:var(--bg2);color:var(--ink);font:inherit;font-size:21px;font-weight:800;text-align:left;cursor:pointer}
.apw .bk-city[aria-checked="true"]{border-color:var(--accent);background:var(--accent-soft)}
.apw .bk-city i{margin-left:auto;font-style:normal;font-size:24px;line-height:1;color:var(--accent-text)}
.apw .bk-other{display:flex;align-items:center;width:100%;min-height:56px;padding:0 20px;border-radius:12px;border:2px solid var(--line);background:transparent;color:var(--ink2);font:inherit;font-size:17px;font-weight:700;text-align:left;cursor:pointer}
.apw .bk-help{margin:22px 0 0;font-size:17px;line-height:1.5;color:var(--ink2)}
.apw .bk-help a{display:inline-flex;align-items:center;min-height:44px;font-weight:800;color:var(--ink);text-decoration:underline;text-decoration-thickness:2px;text-underline-offset:4px;text-decoration-color:var(--accent)}
.apw .bk-box{margin-top:12px;padding:16px;border-radius:12px;background:var(--bg2);border:1px solid var(--line)}
.apw .bk-box>p:first-child{margin:0;font-size:17px;line-height:1.5}
.apw .bk-good{margin-top:18px;padding:16px;border-radius:12px;border:2px solid var(--ok);background:var(--card)}
.apw .bk-good-h{display:flex;align-items:center;gap:10px;margin:0;font-size:20px;font-weight:800;line-height:1.3;color:var(--ink)}
.apw .bk-good-h span{width:28px;height:28px;flex:0 0 28px;border-radius:50%;background:var(--ok);color:#FFFFFF;display:grid;place-items:center}
.apw .bk-good-p{margin:8px 0 0;font-size:17px;line-height:1.5}
.apw .bk-good .btn{width:100%;margin-top:14px}
/* How many dogs (Joe, Nov 19, 2026: "Let's do 1, 2, 3, and then do 4+. Take out the 5 and 6. Let it be easy."): four big
   buttons, the same four the DoodyCalls quote screen has. */
.apw .bk-dogs{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin-top:16px}
.apw .bk-dog{min-height:62px;border-radius:12px;border:2px solid var(--field);background:var(--card);color:var(--ink);font:inherit;font-size:24px;font-weight:800;cursor:pointer}
.apw .bk-dog[aria-checked="true"]{border-color:var(--ink);background:var(--ink);color:var(--bg)}
/* 4+ asks one thing more, as DoodyCalls does: the exact number. 4, 5 and 6 dogs each have their own price, so it is
   three buttons to tap. Only someone who taps 4+ ever sees them. */
.apw .bk-dmore{margin-top:10px;padding:14px 14px 4px;border-radius:12px;background:var(--bg2);border:1px solid var(--line)}
.apw .bk-dq{margin:0;font-size:17px;font-weight:700;line-height:1.3}
.apw .bk-dmore .bk-dogs{grid-template-columns:repeat(3,minmax(0,1fr));margin-top:10px}
.apw .bk-dmore .bk-dog{min-height:56px;padding:0 4px;font-size:20px;white-space:nowrap}
/* the smallest phones (320 wide): "4 dogs" stays on one line */
@media (max-width:359px){.apw .bk-dmore{padding:12px 10px 4px}.apw .bk-dmore .bk-dog{font-size:18px}}
.apw .bk-more{margin:8px 0 0;font-size:16px;line-height:1.5;color:var(--mute)}
.apw .bk-more a{display:inline-flex;align-items:center;min-height:44px;font-weight:700;color:var(--ink)}
.apw .bk-h2{margin:16px 0 0;font-family:var(--f-head);font-stretch:86%;font-weight:800;font-size:25px;line-height:1.1}
.apw .bk-plans{display:flex;flex-direction:column;gap:10px;margin-top:14px}
.apw .bk-plan{display:flex;align-items:center;gap:14px;width:100%;min-height:72px;padding:10px 16px;border-radius:12px;border:2px solid var(--field);background:transparent;color:var(--ink);font:inherit;text-align:left;cursor:pointer}
.apw .bk-plan[aria-checked="true"]{border-color:#FF4A1C;background:rgba(255,74,28,.12)}
.apw .bk-plan .rd{width:26px;height:26px;flex:0 0 26px;border-radius:50%;border:2px solid var(--mute);display:grid;place-items:center}
.apw .bk-plan .rd i{width:12px;height:12px;border-radius:50%;background:transparent}
.apw .bk-plan[aria-checked="true"] .rd{border-color:#FF4A1C}
.apw .bk-plan[aria-checked="true"] .rd i{background:#FF4A1C}
.apw .bk-plan .nm{flex:1;display:flex;flex-direction:column;gap:3px;min-width:0}
.apw .bk-plan .nm b{font-size:19px;font-weight:700;line-height:1.2}
.apw .bk-plan .nm span{font-size:16px;color:var(--mute)}
.apw .bk-plan .wk{display:flex;flex-direction:column;align-items:flex-end;gap:2px;font-family:var(--f-head);font-stretch:86%;font-weight:800;font-size:27px;line-height:1}
.apw .bk-plan .wk small{font-family:var(--f-text);font-stretch:104%;font-size:15px;font-weight:400;color:var(--mute)}
.apw .bk-note{margin:14px 0 0;font-size:16px;line-height:1.5;color:var(--mute)}
/* Joe, Nov 19, 2026, after going through the DoodyCalls sign up ("I like residential community", "How often do you need your
   yard cleaned? Twice weekly, Weekly, Every other week, Monthly, Just once", "it needs to be easy as well for the consumer").
   Who is this for: two big cards, each with a picture. Tapping one moves on. */
.apw .bk-who{display:flex;flex-direction:column;gap:12px;margin-top:18px}
.apw .bk-wc{display:flex;align-items:center;gap:16px;width:100%;min-height:112px;padding:16px 18px;border-radius:14px;border:2px solid var(--line);background:var(--bg2);color:var(--ink);font:inherit;text-align:left;cursor:pointer}
.apw .bk-wc:hover{border-color:var(--accent)}
.apw .bk-wc .wi{width:60px;height:60px;flex:0 0 60px;border-radius:14px;display:grid;place-items:center;background:var(--accent-soft);color:var(--accent-text)}
.apw .bk-wc .wt{flex:1;min-width:0;display:flex;flex-direction:column;gap:5px}
.apw .bk-wc .wt b{font-family:var(--f-head);font-stretch:86%;font-weight:800;font-size:24px;line-height:1.1}
.apw .bk-wc .wt span{font-size:16px;line-height:1.4;color:var(--ink2)}
/* "Free quote." on the community card, on a line of its own (Joe, Nov 19, 2026: "Make sure that gets a free quote") */
.apw .bk-wc .wt em{font-style:normal;font-size:16px;font-weight:800;line-height:1.3;color:var(--accent-text)}
.apw .bk-wc>i{font-style:normal;font-size:26px;line-height:1;color:var(--accent-text)}
/* the smallest phones: a smaller picture leaves the words more room, so each card is two or three lines */
@media (max-width:359px){.apw .bk-wc{gap:12px;min-height:96px;padding:14px}.apw .bk-wc .wi{width:48px;height:48px;flex-basis:48px;border-radius:12px}.apw .bk-wc .wi svg{width:28px;height:28px}.apw .bk-wc .wt b{font-size:22px}}
/* "We scoop in Goodyear": the good news, right after the city is picked */
.apw .bk-ok{display:inline-flex;align-items:center;gap:8px;margin:0 0 14px;padding:6px 14px 6px 7px;border-radius:999px;background:var(--bg2);border:1px solid var(--line);color:var(--ink);font-size:16px;font-weight:700;line-height:1.3}
.apw .bk-ok span{width:24px;height:24px;flex:0 0 24px;border-radius:50%;background:var(--ok);color:#FFFFFF;display:grid;place-items:center}
/* the tag on the plan we point people to: it sits on the top edge of its row */
.apw .bk-plans{gap:14px}
.apw .bk-plan{position:relative}
.apw .bk-plan .tag{position:absolute;top:-14px;right:12px;padding:3px 9px 2px;border-radius:6px;background:#FF4A1C;color:#0E1430;font-family:var(--f-head);font-stretch:90%;font-style:normal;font-weight:850;font-size:15px;letter-spacing:.03em;line-height:1.2;white-space:nowrap}
.apw .bk-plan .wk{text-align:right}
/* How long since the last cleanup: five big rows. Tapping one moves on. */
.apw .bk-last{display:flex;flex-direction:column;gap:10px;margin-top:18px}
.apw .bk-lc{display:flex;align-items:center;gap:12px;width:100%;min-height:64px;padding:10px 18px;border-radius:12px;border:2px solid var(--line);background:var(--bg2);color:var(--ink);font:inherit;text-align:left;cursor:pointer}
.apw .bk-lc[aria-checked="true"]{border-color:var(--accent);background:var(--accent-soft)}
.apw .bk-lc .lt{flex:1;min-width:0;display:flex;flex-direction:column;gap:4px}
.apw .bk-lc .lt b{font-size:21px;font-weight:800;line-height:1.15}
.apw .bk-lc .lt span{font-size:16px;line-height:1.35;color:var(--mute)}
.apw .bk-lc>i{font-style:normal;font-size:24px;line-height:1;color:var(--accent-text)}
/* the community form: what kind of place, as buttons to tap */
.apw .bk-kinds{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin-top:8px}
.apw .bk-kind{min-height:58px;padding:6px 10px;border-radius:12px;border:2px solid var(--line);background:var(--bg2);color:var(--ink);font:inherit;font-size:19px;font-weight:700;cursor:pointer}
.apw .bk-kind[aria-checked="true"]{border-color:var(--accent);background:var(--accent-soft)}
.apw .flab{display:block;margin-top:18px;font-size:17px;font-weight:700}
.apw .flab .opt{font-weight:500;color:var(--mute)}
.apw .fin{display:block;width:100%;height:56px;margin-top:6px;padding:0 16px;border-radius:12px;border:2px solid var(--field);background:var(--card);color:var(--ink);font:inherit;font-size:18px}
.apw .ferr{margin:6px 0 0;font-size:16px;font-weight:700;line-height:1.4;color:var(--accent-text)}
.apw .cbx{display:flex;gap:14px;align-items:flex-start;margin-top:10px;padding:16px;border-radius:12px;border:2px solid var(--field);background:var(--card);cursor:pointer}
.apw .cbx input{width:28px;height:28px;flex:0 0 28px;margin:0;accent-color:#FF4A1C}
.apw .cbx b{display:block;font-size:18px;line-height:1.3}
.apw .cbx small{display:block;margin-top:4px;font-size:16px;line-height:1.45;color:var(--mute)}
.apw .sugs{display:flex;flex-direction:column;margin-top:6px;border-radius:12px;border:2px solid var(--field);background:var(--card);overflow:hidden}
.apw .sug{display:flex;flex-direction:column;gap:2px;width:100%;min-height:56px;padding:10px 14px;border:0;border-top:1px solid var(--line);background:none;color:var(--ink);font:inherit;text-align:left;cursor:pointer}
.apw .sug:first-child{border-top:0}
.apw .sug b{font-size:17px;line-height:1.3}
.apw .sug small{font-size:15px;color:var(--mute)}
.apw .bk-cityl{margin:8px 0 0;font-size:16px;color:var(--mute)}
.apw .bk-zips{display:grid;grid-template-columns:repeat(auto-fit,minmax(92px,1fr));gap:8px;margin-top:8px}
.apw .bk-zip{min-height:58px;border-radius:12px;border:2px solid var(--line);background:var(--bg2);color:var(--ink);font:inherit;font-size:20px;font-weight:700;font-variant-numeric:tabular-nums;cursor:pointer}
.apw .bk-zip[aria-checked="true"]{border-color:var(--accent);background:var(--accent-soft)}
.apw .bk-zipx{display:flex;align-items:center;justify-content:center;width:100%;min-height:52px;margin-top:8px;border-radius:12px;border:2px solid var(--line);background:transparent;color:var(--ink2);font:inherit;font-size:17px;font-weight:700;cursor:pointer}
.apw .bk-zipn{margin:10px 0 0;font-size:16px;line-height:1.5;color:var(--ink2)}
.apw .rec{color:#FF3B3B;font-weight:800;white-space:nowrap}
.apw .rec-note{margin:10px 0 0;font-size:16px;line-height:1.5;color:var(--ink);font-weight:600}
.apw .fine{margin:12px 0 0;font-size:15px;line-height:1.55;color:var(--mute)}
.apw .fine a,.apw .tlink{color:var(--ink);font-weight:700}
.apw .tlink{display:inline-flex;align-items:center;min-height:48px;padding:0;border:0;background:none;font:inherit;font-size:17px;cursor:pointer;text-decoration:underline;text-underline-offset:3px}
.apw .note{display:flex;gap:12px;align-items:flex-start;margin-top:14px;padding:14px 16px;border-radius:12px;background:var(--bg2);font-size:16px;line-height:1.5;color:var(--ink2)}
.apw .demo{display:inline-flex;align-items:center;gap:8px;margin-top:14px;padding:7px 12px;border-radius:8px;background:var(--bg2);border:1px solid var(--line);font-size:15px;font-weight:700;color:var(--mute)}
.apw .paybox{margin-top:16px;min-height:120px;border-radius:12px;overflow:hidden}
.apw .payline{margin:16px 0 0;font-family:var(--f-head);font-stretch:70%;font-weight:800;font-size:clamp(19px,5.6vw,23px);line-height:1.25;color:var(--ink);text-wrap:balance}
.apw .paynote{margin:8px 0 0;font-size:16px;line-height:1.5;color:var(--mute);text-wrap:pretty}
/* what you get, as two lines of a bill: the plan, and the free deodorizing */
.apw .sum{margin:16px 0 0;border-top:1px solid var(--line)}
.apw .sum-r{display:flex;align-items:baseline;justify-content:space-between;gap:12px;padding:14px 0;border-bottom:1px solid var(--line);font-size:17px;line-height:1.3}
.apw .sum-r b{font-family:var(--f-head);font-stretch:86%;font-weight:800;font-size:20px;white-space:nowrap}
.apw .sum .dz{padding:14px 0;border-bottom:1px solid var(--line)}
/* in sign up the deodorizing line is one size down, so the plan price stays the loudest number on the screen */
.apw.bk .dz .dz-n{font-size:20px}
.apw.bk .dz .dz-was{font-size:19px}
.apw.bk .dz .dz-now{font-size:38px}
.apw.bk .dz .dz-tag{font-size:15px}
.apw .bk-safe{margin:14px 0 0;display:flex;align-items:flex-start;gap:8px;font-size:15px;line-height:1.5;color:var(--mute)}
.apw .bk-safe svg{flex:none;margin-top:2px}
.apw .bk-done-n{width:30px;height:30px;flex:0 0 30px;border-radius:50%;background:var(--accent);color:var(--accent-ink);display:grid;place-items:center;font-size:16px;font-weight:700}
.apw .bk-bar{flex:0 0 auto;display:flex;align-items:center;gap:14px;padding:12px 16px calc(14px + env(safe-area-inset-bottom));border-top:1px solid var(--line);background:var(--bg)}
.apw .bk-sum{display:flex;flex-direction:column;gap:3px;min-width:0}
.apw .bk-sum b{font-family:var(--f-head);font-stretch:86%;font-weight:800;font-size:21px;line-height:1;white-space:nowrap}
.apw .bk-sum span{font-size:15px;line-height:1.2;color:var(--mute);white-space:nowrap}
/* a short screen (a phone on its side, a folding phone with its bars showing): the top and bottom take less room */
@media (max-height:560px){
.apw .bk-top{height:50px;flex-basis:50px}
.apw .bh1{font-size:36px}
.apw .bk-body{padding-top:12px}
.apw .bk-bar{padding-top:8px;padding-bottom:calc(8px + env(safe-area-inset-bottom))}
.apw .bk-bar .btn{min-height:50px}
}
