script:
class Component extends DCLogic {
  constructor(props) {
    super(props);
    this.state = Object.assign({
      // Steps: 0 who is this for, then the city (two faces of one step, told apart by `who`), 1 dogs and how often,
      // 7 how long since the last cleanup (every home, since Nov 23, 2026), 2 about you, 3 the email code, 4 the card, 5 done,
      // 6 the community form. The numbers 0 to 5 are the ones the form always had, so 6 and 7 came after.
      dark: this._themeFromProps(), step: 0, who: '', zip: '', city: '', zipSet: true, zipAll: false, other: false, dogs: 2, plan: 'week', last: '',
      name: '', phone: '', email: '', addr: '', txtVisit: false, tried: false, sugs: [], addrNote: '',
      wait: '', waitDone: false, waitBusy: false, waitErr: '',
      code: '', codeErr: '', resent: false, busy: false, err: '',
      payState: 'idle', payErr: '', payBack: false, payFree: null, payLineSrv: '', wName: '', wPhone: '', wAddr: '', wCity: '', wZip: '', wTexts: false, req: false, reqKind: '',
      cKind: '', cOrg: '', cCity: '', cName: '', cPhone: '', cEmail: '', cNote: '', cTried: false
    }, this._initial());
  }
  componentDidMount() { this._themeInit(); }
  componentWillUnmount() { this._themeStop(); this._stopPay(); }
  _themeFromProps() {
    const pt = this.props.theme || 'light';
    if (pt === 'dark') return true;
    if (pt === 'auto' && typeof window !== 'undefined' && window.matchMedia) return window.matchMedia('(prefers-color-scheme: dark)').matches;
    return false;
  }
  _themeInit() {
    if (typeof window === 'undefined' || !window.matchMedia) return;
    this._mq = window.matchMedia('(prefers-color-scheme: dark)');
    this._mqf = () => { if ((this.props.theme || 'light') === 'auto') this.setState({ dark: this._mq.matches }); };
    if (this._mq.addEventListener) this._mq.addEventListener('change', this._mqf);
  }
  _themeStop() {
    if (this._mq && this._mq.removeEventListener) this._mq.removeEventListener('change', this._mqf);
  }
  componentDidUpdate(prev) {
    if (prev.theme !== this.props.theme) this.setState({ dark: this._themeFromProps() });
  }
  _themeVals() {
    const d = !!this.state.dark;
    return {
      themeClass: d ? 'dark' : 'light',
      isDark: d,
      isLight: !d,
      themeLabel: d ? 'Switch to the light look' : 'Switch to the dark look',
      themeMenuLabel: d ? 'Light look' : 'Dark look',
      toggleTheme: () => this.setState({ dark: !this.state.dark })
    };
  }
  _price(id, dogs) {
    // src/prices.json, written into the page when it is built: dollars a month for 1 to 6 dogs.
    const t = {"week": [89, 99, 115, 134, 147, 160], "twice": [189, 189, 202, 215, 228, 241], "eow": [75, 75, 84, 93, 102, 111]};
    if (id === 'once') return 99;  // the one time cleanup: the lowest price, a big job gets a custom quote
    if (!t[id]) return 0;  // Monthly has no set price yet (Joe, Nov 19, 2026): the office sends one
    return t[id][Math.min(6, Math.max(1, dogs)) - 1];
  }
  _per(id, dogs) {
    const visits = { week: 52 / 12, twice: 104 / 12, eow: 26 / 12 };
    return Math.round(this._price(id, dogs) / visits[id]);
  }
  _week(id, dogs) {
    return Math.round(this._price(id, dogs) * 12 / 52);
  }
  _cal(id, onBand) {
    const out = [];
    for (let i = 0; i < 28; i++) {
      const d = i % 7;
      const w = Math.floor(i / 7);
      const on = id === 'week' ? d === 2 : id === 'twice' ? (d === 2 || d === 5) : (d === 2 && w % 2 === 0);
      out.push({ bg: on ? '#FF4A1C' : (onBand ? 'rgba(255,255,255,.16)' : 'var(--line)') });
    }
    return out;
  }
  _plans(onBand, google) {
    const s = this.state;
    // google = true: the plan names on our Google profile (the home page). The sign up form keeps the short names, since it must match the opt in screenshots on /texts/.
    const names = google ? { week: 'Weekly pickup', twice: 'Twice a week pickup', eow: 'Every other week pickup' } : { week: 'Every week', twice: 'Twice a week', eow: 'Every other week' };
    return ['week', 'twice', 'eow'].map((id) => {
      const on = s.plan === id;
      return {
        id: id,
        name: names[id],
        price: '$' + this._price(id, s.dogs),
        per: 'About $' + this._per(id, s.dogs) + ' a visit',
        week: '$' + this._week(id, s.dogs),
        month: '$' + this._price(id, s.dogs) + ' a month',
        on: on,
        pick: () => this.setState({ plan: id }),
        aria: names[id] + ', about $' + this._week(id, s.dogs) + ' a week, billed $' + this._price(id, s.dogs) + ' a month',
        cal: this._cal(id, onBand),
        border: on ? '#FF4A1C' : (onBand ? 'rgba(255,255,255,.18)' : 'var(--field)'),
        bg: on ? 'rgba(255,74,28,.12)' : 'transparent',
        ring: on ? '#FF4A1C' : (onBand ? '#AEB5D8' : 'var(--mute)'),
        dot: on ? '#FF4A1C' : 'transparent'
      };
    });
  }
  componentDidUpdate(prevProps, prev) {
    const s = this.state;
    if (prev.step !== s.step) {
      if (prev.step === 4) this._stopPay();
      if (s.step === 4) this._startPay();
      // Ad tracking (APW.track): sign up started, then the card step. Once each per visit. No personal details.
      if (s.step === 1 && !this._tStart) { this._tStart = 1; this._t('start', this._tPlan()); }
      if (s.step === 4 && !this._tCard && !this._demo()) { this._tCard = 1; this._t('card', this._tPlan()); }
    }
    // The first step has two faces (who is this for, then the city): moving between them is a new screen too.
    if (prev.step !== s.step || prev.who !== s.who) this._focusStep();
    if (s.step < 4 || s.step === 6 || s.step === 7) this._save();
  }
  _apw() { return typeof window !== 'undefined' ? window.APW || null : null; }
  _t(step, d) { const a = this._apw(); if (a && a.track) a.track(step, d); }
  _tPlan() { const s = this.state; return { plan: s.plan, dogs: s.dogs, value: this._price(s.plan, s.dogs) }; }
  _adIds() { const a = this._apw(); return a && a.adIds ? a.adIds() : {}; }
  _cfg() { const a = this._apw(); return (a && a.cfg) || {}; }
  _demo() { const a = this._apw(); return !a || !a.live; }
  _closed() { const a = this._apw(); return !!(a && a.closed); }
  // Just once takes no card on the website: the office sends the price first (Joe, Nov 18, 2026).
  // Monthly came off the form on November 21, 2026 (Joe: "the monthly 'We send your price, custom quote' needs to be removed immediately").
  _quote(plan) { return plan === 'once'; }
  // Every ZIP code we scoop (the same six as ZIPS in the server), and the city button each one belongs to first.
  _zips() { return { '85326': 'Buckeye', '85396': 'Buckeye', '85338': 'Goodyear', '85395': 'Goodyear', '85340': 'Litchfield Park', '85355': 'Citrus Park' }; }
  _zipCity(zip) { return { '85326': 'buckeye', '85396': 'buckeye', '85338': 'goodyear', '85395': 'goodyear', '85340': 'litchfield', '85355': 'citrus' }[zip] || ''; }
  // Step 1 asks for the city, never the ZIP (Joe, Nov 18, 2026: Buckeye, Goodyear, Litchfield Park and Citrus Park, the
  // four main cities. Verrado is in Buckeye, so it has no button of its own). Waddell got its own button on November 24,
  // 2026 (Joe: "Waddell customers can't find their town on the booking form, so they end up on the waitlist even though we
  // serve Waddell"). Its one ZIP code is 85355, the same ZIP code and the same route area as Citrus Park (`citrus` in ZIPS
  // in the server), so the route and the price are the same. The address step asks which ZIP code the
  // home is in. `zips` are the ZIP codes homes in that city have: part of Verrado (the Village District), part of north
  // Goodyear (some of PebbleCreek and Palm Valley) and the south end of Citrus Park have a Litchfield Park 85340 address.
  // "My ZIP code is not here" on that step shows all six, so every ZIP code we scoop can be picked from every city, and a
  // ZIP code that is none of the six gets the phone number.
  _cities() { return [
    { id: 'buckeye', label: 'Buckeye', zips: ['85326', '85396', '85340'] },
    { id: 'goodyear', label: 'Goodyear', zips: ['85338', '85395', '85340'] },
    { id: 'litchfield', label: 'Litchfield Park', zips: ['85340'] },
    { id: 'citrus', label: 'Citrus Park', zips: ['85355', '85340'] },
    { id: 'waddell', label: 'Waddell', zips: ['85355'] }
  ]; }
  _city(id) { return this._cities().filter((c) => c.id === id)[0] || null; }
  // The waitlist safety net (Joe, Nov 24, 2026). On November 22 a Waddell customer found no button for his town, joined
  // the waitlist, and booked three minutes later under Citrus Park. Nobody we scoop for goes on the waitlist any more: a
  // typed city that is one of our towns, or one of the six ZIP codes, gets "Good news, we already serve you" and the sign
  // up with that city and ZIP code picked. The server checks the same thing again (`waitlist` in worker.js).
  _servedTown(text) {
    const t = ' ' + String(text || '').toLowerCase().replace(/[^a-z]+/g, ' ').trim() + ' ';
    const towns = [['citrus park', 'citrus'], ['litchfield', 'litchfield'], ['waddell', 'waddell'], ['verrado', 'buckeye'], ['buckeye', 'buckeye'], ['goodyear', 'goodyear']];
    for (let i = 0; i < towns.length; i++) if (t.indexOf(' ' + towns[i][0] + ' ') >= 0) return towns[i][1];
    return '';
  }
  // What to open the sign up with for a typed city and ZIP code, or null when we do not scoop there. One of the six ZIP
  // codes wins over the city. 85355 is a Waddell ZIP code on the mail, so it reads Waddell unless they typed Citrus Park.
  _served(cityText, zipText) {
    const zip = this._digits(zipText, 5);
    const town = this._servedTown(cityText);
    if (this._zips()[zip]) {
      const c = this._city(town);
      return { city: c && c.zips.indexOf(zip) >= 0 ? town : (zip === '85355' ? 'waddell' : this._zipCity(zip)), zip: zip, zipSet: true };
    }
    if (!town) return null;
    const c = this._city(town);
    return { city: town, zip: c.zips[0], zipSet: c.zips.length === 1 };
  }
  _bookServed(sv) { this.setState(Object.assign({ who: 'home', zipAll: false, other: false, waitDone: false, waitBusy: false, waitErr: '', step: 1, err: '', busy: false }, sv)); }
  _pickCity(c) { this.setState({ who: 'home', city: c.id, zip: c.zips[0], zipSet: c.zips.length === 1, zipAll: false, other: false, waitDone: false, waitErr: '', step: 1, err: '', busy: false }); }
  _initial() {
    if (typeof window === 'undefined') return {};
    const out = {};
    try { Object.assign(out, JSON.parse(sessionStorage.getItem('apw.book') || '{}')); } catch (e) { }
    // A sign up saved before November 19, 2026 has no answer to "Who is this for?". It was a home.
    if (!out.who && (out.step === 1 || out.step === 2)) out.who = 'home';
    if (this.props.mode === 'page') {
      // A link that says what it is for skips the first question: /book/?dogs=3 (the price card), /book/?plan=once,
      // /book/?zip=85338, /book/?for=home. /book/?for=community opens the community form.
      const q = new URLSearchParams(location.search);
      if (/^\d{5}$/.test(q.get('zip') || '')) { out.zip = q.get('zip'); out.city = ''; out.zipSet = true; out.who = 'home'; }
      if (['week', 'twice', 'eow', 'once'].indexOf(q.get('plan')) >= 0) { out.plan = q.get('plan'); out.who = 'home'; }
      const n = parseInt(q.get('dogs'), 10);
      if (n >= 1 && n <= 6) { out.dogs = n; out.who = 'home'; }
      if (q.get('for') === 'home') out.who = 'home';
      if (q.get('for') === 'community') { out.who = 'community'; out.step = 6; }
      else if (out.who === 'home' && out.step === 6) out.step = 0;
    }
    delete out.dayIso;
    // A sign up saved before November 18, 2026 may hold the Verrado button, which is part of Buckeye now.
    if (out.city === 'verrado') out.city = 'buckeye';
    if (out.city && !this._city(out.city)) out.city = '';
    if (out.who !== 'home' && out.who !== 'community') out.who = '';
    if (['week', 'twice', 'eow', 'once'].indexOf(out.plan) < 0) delete out.plan;
    if (['week', '1to4w', '1to3m', '3mplus', 'unsure'].indexOf(out.last) < 0) delete out.last;
    // A saved sign up comes back to the step it was on, as far as about you (2). Never to the code or the card.
    if ([0, 1, 2, 6, 7].indexOf(out.step) < 0) out.step = 0;
    if ((out.step === 1 || out.step === 2 || out.step === 7) && (out.who !== 'home' || !this._zips()[out.zip])) out.step = 0;
    // About you comes after "How long since the last cleanup?". A sign up saved before that question was asked
    // (or with one of its old answers) goes back to it.
    if (out.step === 2 && !out.last) out.step = 7;
    if (out.step === 6 && out.who !== 'community') out.step = 0;
    if (out.step === 0 && out.who === 'community') out.who = '';
    return out;
  }
  _save() {
    if (typeof window === 'undefined') return;
    const s = this.state;
    const keep = { step: s.step === 3 ? 2 : s.step, who: s.who, zip: s.zip, city: s.city, zipSet: s.zipSet, zipAll: s.zipAll, dogs: s.dogs, plan: s.plan, last: s.last, name: s.name, phone: s.phone, email: s.email, addr: s.addr, txtVisit: s.txtVisit,
      cKind: s.cKind, cOrg: s.cOrg, cCity: s.cCity, cName: s.cName, cPhone: s.cPhone, cEmail: s.cEmail, cNote: s.cNote };
    try { sessionStorage.setItem('apw.book', JSON.stringify(keep)); } catch (e) { }
  }
  _clearDraft() { try { sessionStorage.removeItem('apw.book'); } catch (e) { } }
  _focusStep() {
    if (typeof document === 'undefined' || !this.__root) return;
    const body = this.__root.querySelector('.bk-body');
    if (body) body.scrollTop = 0;
    const h = this.__root.querySelector('.bh1');
    if (h && h.focus) { try { h.focus({ preventScroll: true }); } catch (e) { h.focus(); } }
  }
  // Is there a free month? The server says so (/api/config), and checkout answers it again for the card form it made.
  // Before the server has answered (the demo, or a slow start) the build's own sale switch stands in.
  // /book/?nofree=1 turns a free month down for that tab: staff use it to run a sign up that pays today.
  _noFree() { return typeof location !== 'undefined' && /[?&]nofree=1(&|$)/.test(location.search); }
  _free() {
    if (this._noFree()) return false;
    if (typeof this.state.payFree === 'boolean') return this.state.payFree;
    const cfg = this._cfg();
    return typeof cfg.freeMonth === 'boolean' ? cfg.freeMonth : '[[bf:1||0]]' === '1';
  }
  // The same rule as firstCharge in the server, so these dates match what Stripe charges. Every bill is one full
  // month: there are no part months. With a free month the card is saved and nothing is charged. The free month is
  // exactly one month from the sign up day (Joe, Nov 16, 2026: sign up November 16, first bill December 16). The day it
  // ends we charge the month price, and that is the bill day from then on. With no free month we charge the month
  // price today, and today is the bill day. All in Arizona time (noon there is always 19:00 UTC), so it reads the
  // same from any time zone. Once the card form is made, the server sends its own line back and the page shows that
  // one (payLineSrv), so a sign up that crosses midnight still reads the day Stripe will charge.
  _bill(free) {
    const noon = (iso) => new Date(iso + 'T19:00:00Z');
    const plusMonth = (x) => {
      const d = new Date(x.getTime()), dd = d.getUTCDate();
      d.setUTCDate(1);
      d.setUTCMonth(d.getUTCMonth() + 1);
      d.setUTCDate(Math.min(dd, new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + 1, 0)).getUTCDate()));
      return d;
    };
    const day = (x) => x.toLocaleDateString('en-US', { month: 'short', day: 'numeric', timeZone: 'America/Phoenix' });
    const today = new Date(Date.now() - 7 * 3600e3).toISOString().slice(0, 10);
    const out = {};
    // No free month: Stripe starts the plan the moment the card is charged and bills one month later to the second.
    if (!free) { out.nextShort = day(plusMonth(new Date())); return out; }
    out.freeShort = day(plusMonth(noon(today)));
    return out;
  }
  // Street address suggestions (Joe, Nov 16, 2026). Typing a house number and a few letters asks the server for matches
  // inside our towns. Tapping one fills the street and the ZIP. If nothing comes back, the customer just keeps typing.
  _addrTyped(v) {
    this.setState({ addr: v, addrNote: '' });
    clearTimeout(this._addrT);
    const a = this._apw();
    if (!a || this._demo() && !this._closed() || v.trim().length < 3 || !/\d/.test(v)) { if (this.state.sugs.length) this.setState({ sugs: [] }); return; }
    if (!this._addrS) this._addrS = Math.random().toString(36).slice(2, 12) + Date.now().toString(36);
    const n = this._addrN = (this._addrN || 0) + 1;
    this._addrT = setTimeout(() => {
      a.get('/api/address?q=' + encodeURIComponent(v.trim()) + '&s=' + this._addrS).then((r) => {
        if (n === this._addrN && this.state.step === 2) this.setState({ sugs: (r && r.list) || [] });
      }).catch(() => { });
    }, 220);
  }
  async _addrPick(g) {
    const a = this._apw(), tok = this._addrS;
    this._addrN = (this._addrN || 0) + 1; this._addrS = '';
    this.setState({ sugs: [] });
    try {
      const r = await a.get('/api/address/pick?id=' + encodeURIComponent(g.id) + '&s=' + (tok || ''));
      if (!r.served) { this.setState({ addr: r.street, addrNote: 'That home is in ' + (r.city || 'ZIP ' + r.zip) + ', ' + r.zip + '. We do not scoop in that ZIP code yet. If your home is in Buckeye, Goodyear, Litchfield Park, Citrus Park or Waddell, call or text 623.309.6104 and we will check your address.' }); return; }
      const city = this._city(this.state.city);
      const next = { addr: r.street, zip: r.zip, zipSet: true, addrNote: '' };
      // The address is in another city than the button that was tapped: follow the address.
      if (!city || city.zips.indexOf(r.zip) < 0) next.city = this._zipCity(r.zip);
      this.setState(next);
    } catch (e) { this.setState({ addr: g.main }); }
  }
  _digits(v, n) { return String(v || '').replace(/\D/g, '').slice(0, n); }
  _phone10() { let p = String(this.state.phone || '').replace(/\D/g, ''); if (p.length === 11 && p[0] === '1') p = p.slice(1); return p; }
  _errs() {
    const s = this.state;
    return {
      name: s.name.trim().length < 2 ? 'Type your full name.' : '',
      phone: this._phone10().length === 10 ? '' : 'Type your 10 digit mobile number.',
      email: /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(s.email.trim()) ? '' : 'Type your email, like you@email.com.',
      addr: s.addr.trim().length < 5 ? 'Type your street address.' : '',
      zip: s.zipSet === false ? 'Tap your ZIP code.' : ''
    };
  }
  _cPhone10() { return String(this.state.cPhone || '').replace(/\D/g, '').replace(/^1(?=\d{10}$)/, ''); }
  _cErrs() {
    const s = this.state;
    return {
      kind: s.cKind ? '' : 'Tap what kind of place it is.',
      org: s.cOrg.trim().length < 2 ? 'Type the name of your community or business.' : '',
      city: s.cCity.trim().length < 2 ? 'Type your city.' : '',
      name: s.cName.trim().length < 2 ? 'Type your name.' : '',
      phone: this._cPhone10().length === 10 ? '' : 'Type your 10 digit phone number.',
      email: /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(s.cEmail.trim()) ? '' : 'Type your email, like you@email.com.'
    };
  }
  // My community: one short form, no card and no text box. It goes to the office as a commercial lead, and we call or
  // email to set up the free site walk.
  async _community() {
    const s = this.state, e = this._cErrs();
    if (e.kind || e.org || e.city || e.name || e.phone || e.email) { this.setState({ cTried: true }); this._toErr(); return; }
    if (this._demo() && !this._closed()) { this.setState({ req: true, reqKind: 'community', step: 5 }); return; }
    this.setState({ busy: true, err: '' });
    const eid = this._apw().eventId ? this._apw().eventId('cq') : '';
    try {
      await this._apw().post('/api/community', {
        kind: s.cKind, org: s.cOrg.trim(), city: s.cCity.trim(), name: s.cName.trim(), phone: this._cPhone10(), email: s.cEmail.trim(), note: s.cNote.trim(),
        page: location.pathname, website: '', eid: eid, ad: this._adIds()
      });
      this._clearDraft();
      this._t('request', { id: eid, plan: 'community' });
      this.setState({ busy: false, req: true, reqKind: 'community', step: 5, cTried: false });
    } catch (err) { this.setState({ busy: false, err: this._apw().msg(err) }); }
  }
  _go(step) { this.setState({ step: step, err: '', busy: false }); }
  // Continue with something missing: the notes show under each box. The button sits under the form, so the first note
  // may be far up the screen. Bring it into view, with its box above it, so nobody thinks the button did nothing.
  _toErr() {
    setTimeout(() => {
      if (typeof document === 'undefined' || !this.__root) return;
      const body = this.__root.querySelector('.bk-body'), note = body && body.querySelector('.ferr');
      if (!note) return;
      const top = note.getBoundingClientRect().top - body.getBoundingClientRect().top + body.scrollTop - 150;
