      phone: s.phone, onPhone: field('phone'),
      email: s.email, onEmail: field('email'),
      addr: s.addr, onAddr: (e) => this._addrTyped(e.target.value),
      hasSugs: s.step === 2 && s.sugs.length > 0,
      sugs: s.sugs.map((g) => ({ main: g.main, sub: g.sub, pick: () => this._addrPick(g) })),
      eName: errs.name, ePhone: errs.phone, eEmail: errs.email, eAddr: errs.addr || s.addrNote,
      txtVisit: !!s.txtVisit, onTxtVisit: (e) => this.setState({ txtVisit: !!e.target.checked }),
      err: s.err,
      cityLine: s.zipSet === false && cityNow ? cityNow.label + ', AZ' : (cities[s.zip] || 'Buckeye, AZ 85396'),
      code: s.code,
      onCode: (e) => { const v = this._digits(e.target.value, 6); this.setState({ code: v, codeErr: '' }); if (v.length === 6) setTimeout(() => this._verify(), 60); },
      codeErr: s.codeErr,
      isDemo: demo,
      resend: () => this._resend(),
      resendLabel: s.resent ? 'We sent a new code' : 'Send a new code',
      // The pay step says the money in one plain line, the same words as the note Stripe shows by its button.
      payFree: free,
      payTitle: free ? 'Start your free month.' : 'Start your plan.',
      payLine: s.payLineSrv || (free ? '$0 today. Then $' + price + ' a month starting ' + bill.freeShort + '.' : '$' + price + ' today. Then $' + price + ' a month starting ' + bill.nextShort + '.'),
      planLine: names[s.plan] + ', ' + dogsLabel + '.',
      payAgree: free ? 'By starting your free month, you agree to our' : 'By starting your plan, you agree to our',
      payDemo: demo,
      payLive: !demo && s.payState !== 'already',
      payLoading: !demo && s.payState === 'loading',
      paySaving: !demo && s.payState === 'saving',
      payPrepaid: !demo && s.payState === 'prepaid',
      payBackLine: s.payBack ? 'We will send your payment back to your card.' : 'Your card was not charged.',
      payError: !demo && s.payState === 'error',
      payAlready: !demo && s.payState === 'already',
      payErr: s.payErr,
      retryPay: () => this._startPay()
    });
  }
}
